std::shared_ptr<HMCPDataIntf> HMComponentFactory::create_checkpoint_data()
{
    return std::make_shared<HMCPData>(HMCfgHandler::get_supervised_entities(),
                                      HMCfgHandler::get_cp_supervision_ids());
}

std::shared_ptr<HMSupervisedEntityDataIntf> HMComponentFactory::create_se_data()
{
    return std::make_shared<HMSupervisedEntityData>(
        HMCfgHandler::get_supervised_entities());
}

std::shared_ptr<HMHSDataIntf> HMComponentFactory::create_hs_data()
{
    return std::make_shared<HMHSData>();
}

std::shared_ptr<HMGlobalSupervisionDataIntf> HMComponentFactory::create_global_sup_data(const hm_mode_t mode_id)
{
    return std::make_shared<HMGlobalSupervisionData>(mode_id);
}

std::shared_ptr<HMCPProcessorIntf> HMComponentFactory::create_cp_processor(std::shared_ptr<HMCPDataIntf> cp_data,
                                                                           std::shared_ptr<HMSupervisedEntityDataIntf> se_data,
                                                                           std::shared_ptr<HMHSDataIntf> hs_data,
                                                                           std::shared_ptr<HMGlobalSupervisionDataIntf> gs_data)
{
    return std::make_shared<HMCPProcessor>(cp_data,
                                           hs_data,
                                           se_data,
                                           gs_data);
}

std::shared_ptr<HMDataReceiverIntf<HMTPCheckpoint, HMCPProcessorIntf>> HMComponentFactory::create_cp_receiver()
{
    return std::make_shared<HMDataFastDDSReceiver<HMTPCheckpoint, HMCPProcessorIntf, HMTPCheckpointPubSubType>>(
        HMCfgHandler::get_cp_subscriber_qos_name(),
        HMCfgHandler::get_cp_msg_type_name(),
        HMCfgHandler::get_cp_topic_name());
}

std::shared_ptr<HMLocalStatusProcessorIntf>
    HMComponentFactory::create_local_status_processor(std::shared_ptr<HMCPDataIntf> cp_data,
                                                      std::shared_ptr<HMSupervisedEntityDataIntf> se_data,
                                                      std::shared_ptr<HMHSDataIntf> hs_data,
                                                      std::shared_ptr<HMGlobalSupervisionDataIntf> gs_data)
{
    return std::make_shared<HMLocalStatusProcessor>(cp_data,
                                                    hs_data,
                                                    se_data,
                                                    gs_data);
}

std::shared_ptr<HMGlobalStatusProcessorIntf>
    HMComponentFactory::create_global_status_processor(std::shared_ptr<HMCPDataIntf> cp_data,
                                                       std::shared_ptr<HMSupervisedEntityDataIntf> se_data,
                                                       std::shared_ptr<HMHSDataIntf> hs_data,
                                                       std::shared_ptr<HMGlobalSupervisionDataIntf> gs_data)
{
    return std::make_shared<HMGlobalStatusProcessor>(cp_data,
                                                     hs_data,
                                                     se_data,
                                                     gs_data);
}

std::unique_ptr<HMDataSenderIntf<HMTPRecoveryCmd>> HMComponentFactory::create_recovery_cmd_sender()
{
    return std::make_unique<HMDataFastDDSSender<HMTPRecoveryCmd, HMTPRecoveryCmdPubSubType>>(
        HMCfgHandler::get_recovery_cmd_publisher_qos_name(),
        HMCfgHandler::get_recovery_cmd_msg_type_name(),
        HMCfgHandler::get_recovery_cmd_topic_name());
}

std::shared_ptr<HMFailureHandlerIntf>
    HMComponentFactory::create_failure_handler(std::shared_ptr<HMCPDataIntf> cp_data,
                                               std::shared_ptr<HMSupervisedEntityDataIntf> se_data,
                                               std::shared_ptr<HMHSDataIntf> hs_data,
                                               std::shared_ptr<HMGlobalSupervisionDataIntf> gs_data,
                                               std::unique_ptr<HMDataSenderIntf<HMTPRecoveryCmd>> recovery_cmd_sender)
{
    return std::make_shared<HMFailureHandler>(cp_data,
                                              hs_data,
                                              se_data,
                                              gs_data,
                                              std::move(recovery_cmd_sender));
}

std::unique_ptr<HMDataSenderIntf<HMTPSupervisionStatus>> HMComponentFactory::create_supervision_status_sender()
{
    return std::make_unique<HMDataFastDDSSender<HMTPSupervisionStatus, HMTPSupervisionStatusPubSubType>>(
        HMCfgHandler::get_sup_status_publisher_qos_name(),
        HMCfgHandler::get_sup_status_msg_type_name(),
        HMCfgHandler::get_sup_status_topic_name());
}

std::shared_ptr<HMStatusReporterIntf>
    HMComponentFactory::create_status_reporter(std::shared_ptr<HMCPDataIntf> cp_data,
                                               std::shared_ptr<HMSupervisedEntityDataIntf> se_data,
                                               std::shared_ptr<HMHSDataIntf> hs_data,
                                               std::shared_ptr<HMGlobalSupervisionDataIntf> gs_data,
                                               std::unique_ptr<HMDataSenderIntf<HMTPSupervisionStatus>> status_sender)
{
    return std::make_shared<HMStatusReporter>(cp_data,
                                              hs_data,
                                              se_data,
                                              gs_data,
                                              std::move(status_sender));
}
